-- Yogurt Order System
-- Current DB option-data update
-- 2026-09-07
--
-- 목적:
-- 기존 메뉴/카테고리/주문 구조는 유지하고
-- 현재 6개 공통 옵션 그룹 + 실제 옵션 아이템 데이터만 교체합니다.

begin;

-- ============================================================
-- 1. 기존 테스트 옵션 아이템 삭제
--    주문 기록이 존재하더라도 order_item_options.option_item_id는
--    ON DELETE SET NULL이며 스냅샷 이름/가격은 유지됩니다.
-- ============================================================

delete from public.option_items
where option_group_id in (
  '30000000-0000-0000-0000-000000000001',
  '30000000-0000-0000-0000-000000000002',
  '30000000-0000-0000-0000-000000000003',
  '30000000-0000-0000-0000-000000000004',
  '30000000-0000-0000-0000-000000000005',
  '30000000-0000-0000-0000-000000000006'
);

-- ============================================================
-- 2. 기존 옵션 그룹 6개를 실제 운영 규칙으로 갱신
-- ============================================================

update public.option_groups
set
  name = '사이즈 선택(기본)',
  selection_type = 'single',
  is_required = true,
  min_select = 1,
  max_select = 1,
  display_order = 0,
  is_active = true
where id = '30000000-0000-0000-0000-000000000001';

update public.option_groups
