--    마이그레이션 때 이미 생성됐지만, 값이 확실히 맞도록 upsert
-- ============================================================

insert into public.menu_option_groups (
  menu_id,
  option_group_id,
  display_order,
  is_active
)
values
  ('20000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000001', 0, true),
  ('20000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002', 1, true),
  ('20000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000003', 2, true),
  ('20000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000004', 3, true),
  ('20000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000005', 4, true),
  ('20000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000006', 5, true)
on conflict (menu_id, option_group_id)
do update set
  display_order = excluded.display_order,
  is_active = excluded.is_active;

commit;

-- ============================================================
-- 실행 후 확인용 SELECT
-- ============================================================

select
  og.name as option_group_name,
  og.selection_type,
  og.min_select,
  og.max_select,
  count(oi.id) as item_count
from public.option_groups og
left join public.option_items oi
  on oi.option_group_id = og.id
where og.id in (
  '30000000-0000-0000-0000-000000000001',
  '30000000-0000-0000-0000-000000000002',
  '30000000-0000-0000-0000-000000000003',
  '30000000-0000-0000-0000-000000000004',
  '30000000-0000-0000-0000-000000000005',
  '30000000-0000-0000-0000-000000000006'
)
group by
  og.id,
  og.name,
  og.selection_type,
  og.min_select,
  og.max_select,
  og.display_order
order by og.display_order;
